'use strict'

class Parser {
  constructor (source) {
    this.tokens = source.split(' ')
    this.index = 0
    this.stack = []
  }

  * parse () {
    while (this.index < this.tokens.length) {
      const done = yield * this.step()
      if (done) return 'stopped'
    }
    return yield * this.end()
  }

  * step () {
    const token = this.tokens[this.index++]
    if (token === '{') return yield * this.blockMap(token)
    if (token === '[') return yield * this.flowSeq(token)
    if (token === '!') return true
    return yield * this.scalar(token)
  }

  * blockMap (open) {
    this.stack.push(open)
    yield { type: 'map-start', depth: this.stack.length }
    while (this.index < this.tokens.length && this.tokens[this.index] !== '}') {
      const stop = yield * this.step()
      if (stop) return stop
    }
    this.index++
    this.stack.pop()
    const reply = yield { type: 'map-end', depth: this.stack.length + 1 }
    if (reply !== undefined) yield { type: 'reply', value: reply }
    return false
  }

  * flowSeq (open) {
    this.stack.push(open)
    let count = 0
    while (this.index < this.tokens.length && this.tokens[this.index] !== ']') {
      yield * this.step()
      count++
    }
    this.index++
    this.stack.pop()
    yield { type: 'seq', count }
    return false
  }

  * scalar (token) {
    const value = yield { type: 'scalar', source: token }
    if (value !== undefined) return yield * this.scalar(String(value))
    return false
  }

  * end () {
    yield { type: 'end', depth: this.stack.length }
    return this.index
  }
}

function parseTokens (source) {
  const tokens = []
  for (const token of new Parser(source).parse()) tokens.push(JSON.stringify(token))
  return tokens
}

// next(value) reaches the innermost delegated generator, and return values
// pass back through each yield*.
function drive (source) {
  const parser = new Parser(source).parse()
  const log = []
  let result = parser.next()
  while (!result.done) {
    const value = result.value
    log.push(JSON.stringify(value))
    result = parser.next(value.type === 'map-end' ? 'ack' : value.source === 'x' ? 'x2' : undefined)
  }
  log.push('return ' + result.value)
  return log.join('\n')
}

function spreadTypes (source) {
  const tokens = [...new Parser(source).parse()]
  return tokens.length + ' ' + tokens.map((token) => token.type).join(',')
}

// Async generator methods with the same mutual recursion.
class AsyncWalker {
  constructor (source) {
    this.tokens = source.split(' ')
    this.index = 0
  }

  async * walk () {
    while (this.index < this.tokens.length) yield * this.next()
    return this.index
  }

  async * next () {
    const token = this.tokens[this.index++]
    await null
    if (token === '(') return yield * this.group()
    yield token
    return token
  }

  async * group () {
    const inner = []
    while (this.tokens[this.index] !== ')') inner.push(yield * this.next())
    this.index++
    yield 'group:' + inner.join('+')
    return inner.length
  }
}

async function walkAll (source) {
  const seen = []
  const walker = new AsyncWalker(source).walk()
  let result = await walker.next()
  while (!result.done) {
    seen.push(result.value)
    result = await walker.next()
  }
  return seen.join(' ') + ' -> ' + result.value
}

module.exports = { parseTokens, drive, spreadTypes, walkAll }
